// Copies the PDF.js worker, standard fonts and cMaps into public/pdfjs/ so the
// viewer loads them from our own origin. The worker must be the exact pdfjs-dist
// version that react-pdf uses, so it is resolved through react-pdf.
// Output is gitignored and regenerated by predev/prebuild.

import { cp, mkdir, rm } from "node:fs/promises";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = join(dirname(fileURLToPath(import.meta.url)), "..");
const require = createRequire(import.meta.url);
const reactPdf = require.resolve("react-pdf");
const pdfjsDir = dirname(require.resolve("pdfjs-dist/package.json", { paths: [reactPdf] }));
const out = join(ROOT, "public", "pdfjs");

await rm(out, { recursive: true, force: true });
await mkdir(out, { recursive: true });
await cp(join(pdfjsDir, "build", "pdf.worker.min.mjs"), join(out, "pdf.worker.min.mjs"));
await cp(join(pdfjsDir, "standard_fonts"), join(out, "standard_fonts"), { recursive: true });
await cp(join(pdfjsDir, "cmaps"), join(out, "cmaps"), { recursive: true });

const { version } = require(join(pdfjsDir, "package.json"));
console.log(`pdfjs-dist ${version} assets copied to public/pdfjs/`);
